package main

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"

	"k8s.io/apimachinery/pkg/util/sets"
	prowconfig "sigs.k8s.io/prow/pkg/config"
	"sigs.k8s.io/yaml"

	releaseconfig "github.com/openshift/ci-tools/pkg/release/config"
	"github.com/openshift/ci-tools/pkg/util/gzip"
)

// aggregateTemplateAnnotation identifies the placement template of a synthesized job.
const aggregateTemplateAnnotation = "dispatcher.openshift.io/aggregate-template"

// loadAggregateJobs reads the exact controller job names generated by release-controller.
func loadAggregateJobs(directory string) (map[string]string, error) {
	aliases := map[string]string{}
	if directory == "" {
		return aliases, nil
	}
	err := filepath.WalkDir(directory, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() || filepath.Ext(path) != ".json" {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var config releaseconfig.Config
		if err := json.Unmarshal(data, &config); err != nil {
			return fmt.Errorf("read release configuration %s: %w", path, err)
		}
		for name, verification := range config.Verify {
			aggregate := verification.AggregatedProwJob
			if aggregate == nil || aggregate.AnalysisJobCount <= 0 {
				continue
			}
			template := "release-openshift-release-analysis-aggregator"
			if aggregate.ProwJob != nil && aggregate.ProwJob.Name != "" {
				template = aggregate.ProwJob.Name
			}
			alias := name + "-" + template
			if previous, found := aliases[alias]; found && previous != template {
				return fmt.Errorf("aggregate job %q references multiple templates", alias)
			}
			aliases[alias] = template
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("load aggregate jobs: %w", err)
	}
	return aliases, nil
}

// validateAggregateJobNames rejects identities shared by generated and configured jobs.
func validateAggregateJobNames(files []fileSizeInfo, aliases map[string]string) error {
	if len(aliases) == 0 {
		return nil
	}
	for _, file := range files {
		data, err := gzip.ReadFileMaybeGZIP(file.path)
		if err != nil {
			return fmt.Errorf("read job configuration %q: %w", file.path, err)
		}
		var config prowconfig.JobConfig
		if err := yaml.Unmarshal(data, &config); err != nil {
			return fmt.Errorf("read job configuration %q: %w", file.path, err)
		}
		names := sets.New[string]()
		addConfiguredJobNames(&config, names)
		for _, name := range sets.List(names) {
			if _, found := aliases[name]; found {
				return fmt.Errorf("aggregate job %q collides with configured job in %q", name, file.path)
			}
		}
	}
	return nil
}

// expandAggregateJobs adds controller jobs to their template's configuration group.
func expandAggregateJobs(config *prowconfig.JobConfig, aliases map[string]string) {
	if len(config.Periodics) == 0 || len(aliases) == 0 {
		return
	}
	existing := sets.New[string]()
	addConfiguredJobNames(config, existing)
	templates := make(map[string]prowconfig.Periodic, len(config.Periodics))
	for _, template := range config.Periodics {
		templates[template.Name] = template
	}
	var names []string
	for name, template := range aliases {
		if _, found := templates[template]; found && !existing.Has(name) {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	for _, name := range names {
		template := templates[aliases[name]]
		job := template
		job.JobBase = *template.JobBase.DeepCopy()
		job.Name = name
		if job.Annotations == nil {
			job.Annotations = map[string]string{}
		}
		job.Annotations[aggregateTemplateAnnotation] = template.Name
		config.Periodics = append(config.Periodics, job)
	}
}

// placementJobBase preserves template eligibility without changing the demand identity.
func placementJobBase(job prowconfig.JobBase) prowconfig.JobBase {
	if template := job.Annotations[aggregateTemplateAnnotation]; template != "" {
		job.Name = template
	}
	return job
}
